// Reads the webhook body: { question, doc_ids?, as_of_date?, k?, meta_filter? }  (chatInput also accepted)
const body = $('Webhook').first().json.body || {};
const cfg = $('Config').first().json;
const question = String(body.question ?? body.chatInput ?? '').trim();
let ids = body.doc_ids;
if (typeof ids === 'string') ids = ids.split(',');
ids = Array.isArray(ids) ? ids.map(s => String(s).trim()).filter(Boolean) : [];
const asOf = /^\d{4}-\d{2}-\d{2}$/.test(String(body.as_of_date || '')) ? body.as_of_date : null;
const k = Math.min(Math.max(parseInt(body.k ?? cfg.top_k, 10) || cfg.top_k, 1), 50);
const meta = body.meta_filter && typeof body.meta_filter === 'object' && !Array.isArray(body.meta_filter) ? body.meta_filter : {};
let error = null;
if (!question) error = 'question is required';
else if (question.length > 2000) error = 'question is too long (max 2000 characters)';
else if (body.as_of_date && !asOf) error = 'as_of_date must be YYYY-MM-DD';
else if (Object.values(meta).some(v => !['string', 'number', 'boolean'].includes(typeof v))) error = 'meta_filter values must be strings, numbers or booleans';
return [{ json: { question, doc_ids: ids.length ? ids : null, as_of_date: asOf, k, meta_filter: meta, started: Date.now(), error } }];

// Mirrors backend/app/rag/answer.py (usable_rows, build_messages). A test runs this code and the Python side on the same
// rows and compares the prompts. The system prompt is generated from backend/app/rag/prompts/answer_system.txt:
// do not edit it here, run `python -m app.rag n8n-export`.
const cfg = $('Config').first().json;
const SYSTEM = __SYSTEM_PROMPT__;
const rows = $input.all().map(i => i.json).filter(r => r && r.chunk_id);
const score = r => (r.similarity === null || r.similarity === undefined) ? null : Math.round(Number(r.similarity) * 1000) / 1000;
// Everything the search returned, before the similarity floor: retrieval quality is measured on this.
const ranked = rows.map(r => ({ chunk_id: r.chunk_id, section_id: r.section_id, similarity: score(r) }));
const kept = rows.filter(r => Number(r.similarity ?? 0) >= Number(cfg.min_similarity));
const retrieved = [...new Set(kept.map(r => r.section_id))];
const scores = kept.map(r => ({ chunk_id: r.chunk_id, section_id: r.section_id, similarity: score(r) }));
if (!kept.length) return [{ json: { has_context: false, retrieved, scores, ranked, contains: [] } }];
const contains = kept.flatMap(r => (r.metadata && r.metadata.contains) || []);
const header = r => {
  const m = r.metadata || {};
  const where = [
    m.title || r.doc_id,
    r.version ? `version ${r.version}` : null,
    (r.heading_path || []).join(' > ') || null,
    r.page_start ? (r.page_start === r.page_end ? `p. ${r.page_start}` : `pp. ${r.page_start}-${r.page_end}`) : null,
    m.contains && m.contains.length ? `contains: ${m.contains.join(', ')}` : null,
  ].filter(Boolean);
  return `[${r.section_id}] (${where.join(' | ')})`;
};
const passages = kept.map(r => `${header(r)}\n${r.content}`).join('\n\n---\n\n');
const req = $('Normalise request').first().json;
const payload = {
  model: cfg.llm_model,
  temperature: 0,
  max_tokens: cfg.llm_max_tokens,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: SYSTEM },
    { role: 'user', content: `PASSAGES:\n\n${passages}\n\nQUESTION: ${req.question}` },
  ],
};
return [{ json: { has_context: true, payload, retrieved, scores, ranked, contains } }];

// Mirrors backend/app/rag/answer.py (answer_question). Rules enforced here, not left to the model:
//  * citations are kept only if they name a retrieved section (or one listed in a chunk's `contains`);
//  * an answer with no valid citation becomes an abstention;
//  * a failed or unparseable model reply is an abstention with the error, never an invented answer.
const cfg = $('Config').first().json;
const built = $('Build prompt').first().json;
const req = $('Normalise request').first().json;
const res = $input.first().json;
const NOT_FOUND = 'Not found in the provided documents.';
const base = { retrieved: built.retrieved, scores: built.scores, ranked: built.ranked, latency_ms: Date.now() - req.started };
const abstain = (answer, reason, extra) => ({ answer, citations: [], unsupported_citations: [], abstained: true, abstain_reason: reason, ...base, ...extra });
let data;
try {
  const text = res.choices?.[0]?.message?.content;
  if (typeof text !== 'string' || !text) throw new Error(res.error?.message || 'empty or unexpected model response');
  data = JSON.parse(text.replace(/```(?:json)?/g, '').trim());
  if (data === null || typeof data !== 'object' || Array.isArray(data)) throw new Error('answer is not a JSON object');
} catch (e) {
  return [{ json: abstain('Sorry, the answer could not be generated.', 'llm_error', { error: String(e.message || e).slice(0, 300) }) }];
}
const allowed = new Set([...built.retrieved, ...built.contains]);
const claimed = [...new Set(Array.isArray(data.citations) ? data.citations.map(String) : [])];
const inText = [...new Set([...String(data.answer || '').matchAll(/\[([a-z]+:[A-Za-z0-9._-]+)\]/g)].map(m => m[1]))].filter(i => !claimed.includes(i));
const valid = claimed.filter(c => allowed.has(c));
const unsupported = [...claimed, ...inText].filter(c => !allowed.has(c));
const meta = { model: res.model || cfg.llm_model, usage: res.usage };
if (data.abstained === true) return [{ json: abstain(NOT_FOUND, 'model', { unsupported_citations: unsupported, ...meta }) }];
if (!valid.length) return [{ json: abstain(NOT_FOUND, 'no_valid_citations', { unsupported_citations: unsupported, ...meta }) }];
return [{ json: { answer: String(data.answer || '').trim(), citations: valid, unsupported_citations: unsupported, abstained: false, ...base, ...meta } }];

// No passage reached the similarity floor: answer "not found" without calling the model.
const req = $('Normalise request').first().json;
return [{ json: { answer: 'Not found in the provided documents.', citations: [], unsupported_citations: [], abstained: true,
  abstain_reason: 'no_passages', retrieved: $json.retrieved, scores: $json.scores, ranked: $json.ranked, latency_ms: Date.now() - req.started } }];
